const steps=['Receipt','Friends','Split','Settle'];
const colors=['#fce2d9','#e2e7fe','#def0db','#f7e9c7','#e9dffa','#d5edf2'];
function Avatar({name,index=0,small=false}:{name:string,index?:number,small?:boolean}){return <span className={`avatar ${small?'small':''}`} style={{background:colors[index%colors.length]}}>{name.slice(0,1).toUpperCase()}</span>;}
function NetworkMark({network}:{network:Network}){return <span className={`network-mark ${network}`}>{network==='base'?'—':network==='stellar'?'✦':'≋'}</span>;}
function AmountInput({value,onChange,label,precision=2}:{value:number,onChange:(n:number)=>void,label:string,precision?:number}){return <input aria-label={label} inputMode="decimal" type="number" min="0" max="1000000" step={10**-precision} value={value/10**precision||''} placeholder="0.00" onChange={e=>onChange(Math.max(0,decimalToUnits(e.target.value,precision)))}/>;}
async function api(path:string,body:unknown){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw new Error(d.error||'Please try again.');return d;}
async function prepareImage(file:File):Promise<{image:string;mimeType:string;preview:string}>{
  if(file.size>25*1024*1024)throw new Error('Choose a photo smaller than 25 MB.');
  const url=URL.createObjectURL(file);
  try{
    const img=new Image();img.src=url;
    await new Promise<void>((resolve,reject)=>{img.onload=()=>resolve();img.onerror=()=>reject(new Error('This photo format is not supported by your browser. Take a new photo or choose a JPEG, PNG, or WebP.'));});
    const scale=Math.min(1,2000/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);
    const ctx=canvas.getContext('2d');if(!ctx)throw new Error('Could not prepare the photo.');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);
    const preview=canvas.toDataURL('image/jpeg',0.88);
    if(preview.length>3_700_000)throw new Error('This image is still too large. Crop to the receipt and try again.');
    return {preview,image:preview.split(',')[1],mimeType:'image/jpeg'};
  }finally{URL.revokeObjectURL(url);}
}

