  useEffect(()=>{setQr('');if(uri&&modal==='payment')import('qrcode').then(q=>q.toDataURL(uri,{width:256,margin:2,color:{dark:'#202421',light:'#ffffff'}})).then(setQr).catch(()=>setError('Could not create the QR code. Use the payment link.'));},[uri,modal]);
  async function authorizedApi(path:string,body:unknown){const r=await fetch(path,{method:'POST',headers:{...await session.headers(),'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw new Error(d.error||'Please try again.');return d;}
  function change(patch:Partial<Bill>){if(shared)return;setBill(b=>b?{...b,...patch}:b);setDirty(true);setError('');}
  async function saveDraft(){if(!bill||busy)return;try{await account.save(bill,token,editToken,dirty,preview,groupVersion.current);setToast('Saved to your account.');}catch(e){notifyError(e);}}
  async function openCloud(entry:CloudBill){scanRequest.current?.abort();activeBillId.current=entry.bill.id;account.open(entry);skipRestore.current=entry.bill.id;groupVersion.current=entry.roomVersion||0;setBill(entry.bill);setGroup(null);setToken(entry.token||'');setEditToken(entry.editToken||'');setDirty(!!entry.dirty);setCanEdit(!!entry.editToken);setShareUrl(entry.token?`${window.location.origin}/s#${entry.token}`:'');setPreview('');setStep(0);setView('bill');setError('');if(entry.token&&!entry.dirty){try{const d=await authorizedApi('/api/share',{token:entry.token,editToken:entry.editToken});if(activeBillId.current!==entry.bill.id)return;applyGroup(d.bill,d.group);setCanEdit(d.canEdit);}catch(e){notifyError(e);}}if(entry.hasPhoto){try{const r=await fetch('/api/photo',{method:'POST',headers:{...await session.headers(),'Content-Type':'application/json'},body:JSON.stringify({billId:entry.bill.id})});if(!r.ok)throw new Error('Could not load the saved photo.');const reader=new FileReader();reader.onload=()=>{if(activeBillId.current!==entry.bill.id)return;setPreview(String(reader.result));void savePhoto(entry.bill.id,String(reader.result));};reader.readAsDataURL(await r.blob());}catch(e){notifyError(e);}}}
