  function cancelScan(){scanRequest.current?.abort();setToast('Receipt upload cancelled.');}
  function addFriend(contact:Contact){if(!bill)return;if(bill.people.length>=20)throw new Error('A bill can include up to 20 people.');if(bill.people.some(p=>contact.email?p.email?.toLowerCase()===contact.email.toLowerCase():p.name.toLowerCase()===contact.name.toLowerCase()))throw new Error('This friend is already listed.');const id=crypto.randomUUID();change({people:[...bill.people,{id,name:contact.name,email:contact.email}]});account.remember(contact);}
