  function whatsappText(){if(!bill)return '';const payer=bill.people.find(p=>p.id===bill.payerId)?.name;return `Here’s our split for ${bill.title} 🧾\n${allShares.filter(p=>p.id!==bill.payerId).map(p=>`${p.name}: ${(p.usdc/100).toFixed(2)} USDC`).join('\n')}\nPay ${payer} in USDC or with PayPal using the link.\n${shareUrl}`;}
